export function prixTTC(prixHT, taux = 0.2) {
  if (typeof prixHT !== 'number' || Number.isNaN(prixHT)) throw new TypeError('prix invalide');
  if (prixHT < 0) throw new RangeError('prix negatif');
  return Math.round(prixHT * (1 + taux) * 100) / 100;
}

